import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { roundCents } from './money.js';
import { isValidDate, addDays } from './dates.js';

function validateDiscount(discountPercent) {
  if (discountPercent === undefined || discountPercent === null) return true;
  return typeof discountPercent === 'number' && discountPercent >= 0 && discountPercent <= 100;
}

function calculateDueDate(issueDate, terms) {
  if (terms === 'NET14') return addDays(issueDate, 14);
  if (terms === 'NET30') return addDays(issueDate, 30);
  if (terms === 'EOM') {
    const [year, month] = issueDate.split('-');
    const monthNum = Number(month);
    const nextMonthNum = monthNum === 12 ? 1 : monthNum + 1;
    const nextYear = monthNum === 12 ? Number(year) + 1 : year;
    const nextMonth = String(nextMonthNum).padStart(2, '0');
    const firstOfNextMonth = `${nextYear}-${nextMonth}-01`;
    return addDays(firstOfNextMonth, -1);
  }
  return null;
}

/**
 * Create an invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }>, terms?: string }} input
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array, terms: string, dueDate: string } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms }) {
  // Default terms to NET30
  const finalTerms = terms ?? 'NET30';

  // Validate terms
  if (!['NET14', 'NET30', 'EOM'].includes(finalTerms)) {
    return fail('TERMS_INVALID');
  }

  // Normalize customer ID
  const normalizedCustomerId = normalizeId(customerId);

  // Validate customer exists
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;
  const customer = customerResult.value;

  // Validate date format (YYYY-MM-DD) and that it's a real date
  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  // Validate lines is not empty
  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  // Build invoice lines with product details
  const invoiceLines = [];
  for (const line of lines) {
    // Validate qty
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    // Validate discount
    if (!validateDiscount(line.discountPercent)) return fail('DISCOUNT_INVALID');

    // Validate SKU and get product details
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    const newLine = {
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    };
    // Use provided discount, or fall back to tier discount
    const discount = line.discountPercent !== undefined ? line.discountPercent : TIER_DISCOUNTS[customer.tier];
    if (discount !== 0) {
      newLine.discountPercent = discount;
    }
    invoiceLines.push(newLine);
  }

  const dueDate = calculateDueDate(issueDate, finalTerms);

  return ok({
    customerId: normalizedCustomerId,
    issueDate,
    status: 'draft',
    terms: finalTerms,
    dueDate,
    lines: invoiceLines,
  });
}

/**
 * Calculate the total for a single line: qty * unitPrice (in cents).
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number}
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate the discount for a single line: lineTotal * discountPercent / 100 (in cents).
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
 * @returns {number}
 */
export function lineDiscount(line) {
  const discountPercent = line.discountPercent ?? 0;
  return roundCents(lineTotal(line) * discountPercent / 100);
}

/**
 * Calculate the VAT for a single line: (lineTotal - lineDiscount) * vatRate / 100 (in cents).
 * @param {{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }} line
 * @returns {number}
 */
export function lineVat(line) {
  const netAmount = lineTotal(line) - lineDiscount(line);
  return roundCents(netAmount * line.vatRate / 100);
}

/**
 * Calculate totals for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }> }} invoice
 * @returns {{ subtotal: number, discount: number, vat: number, total: number }}
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const discount = invoice.lines.reduce((sum, line) => sum + lineDiscount(line), 0);
  const vat = invoice.lines.reduce((sum, line) => sum + lineVat(line), 0);
  const total = Math.max(0, subtotal - discount + vat);
  return {
    subtotal,
    discount,
    vat,
    total,
  };
}

/**
 * Add a line to an invoice, or increase qty if SKU already exists.
 * @param {{ status: string, lines: Array, customerId: string, issueDate: string }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} input
 * @returns {{ ok: true, value } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  // Check invoice is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Validate qty
  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  // Validate discount
  if (!validateDiscount(discountPercent)) return fail('DISCOUNT_INVALID');

  // Validate SKU and get product details
  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;
  const newLines = invoice.lines.map((line) => ({ ...line }));
  const existingLine = newLines.find((line) => line.sku === sku);

  if (existingLine) {
    existingLine.qty += qty;
  } else {
    const newLine = {
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    };
    if (discountPercent !== undefined) {
      newLine.discountPercent = discountPercent;
    }
    newLines.push(newLine);
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from an invoice by SKU.
 * @param {{ status: string, lines: Array, customerId: string, issueDate: string }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  // Check invoice is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Check SKU exists on invoice
  if (!invoice.lines.find((line) => line.sku === sku)) return fail('LINE_NOT_FOUND');

  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  // Check would not remove last line
  if (newLines.length === 0) return fail('NO_LINES');

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Issue an invoice, assigning it a number and changing status to 'issued'.
 * @param {{ status: string, lines: Array, customerId: string, issueDate: string }} invoice
 * @param {string[]} existingNumbers - Array of existing invoice numbers
 * @returns {{ ok: true, value } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  // Check invoice is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    ...invoice,
    number,
    status: 'issued',
  });
}

